-- Passage rg4-theme-summary-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('0692db4c-3f53-5f05-a264-2d68637edac0', 'rg4-theme-summary-p01', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$The Firefly Who Could Not Wait$q$, $q$At the edge of a pond lived a young firefly named Pip. Every evening, he watched the older fireflies light up the tall grass. Their glow was soft and steady, like tiny lanterns.

"I want to shine brighter than all of them," Pip said. So one afternoon, long before sunset, he flashed his light as hard as he could. He flashed and flashed until his tail felt warm and tired.

A turtle on a log blinked at him. "Why are you glowing now?" she asked. "The sun is still up. No one can see you."

Pip did not listen. He kept flashing until the sky turned orange. By the time the first stars came out, his light was weak. It flickered once and then went dim.

All around him, the other fireflies began to glow. The meadow sparkled like a sky full of stars. Pip could only sit on a blade of grass and watch.

The next evening, Pip rested quietly through the long afternoon. He waited until the sky was dark and the frogs began to sing. Then he lifted into the air and let his light shine. It was not the brightest light in the meadow, but it glowed all night long.

The turtle smiled from her log. "Now everyone can see you," she said.$q$, 'draft')
