-- Passage rg4-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ceb8ce6c-ed9b-5a58-8153-17e57a57c3c5', 'rg4-theme-summary-p02', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$The Squeaky Trumpet$q$, $q$On the first day of band, Amara lifted her new trumpet and blew. Instead of a clear note, out came a squeak like a rubber duck. A few kids giggled. Amara's cheeks felt hot.

That night she told her uncle, "I'm going to quit. Everyone else already sounds good."

Uncle Desmond played the guitar at weddings. He pulled a worn notebook off his shelf. Inside were pages of dates, each with a number beside it. "When I started, I practiced ten minutes a day," he said. "I wrote it down so I could see I was really trying."

Amara made her own chart. Every day after homework, she practiced for ten minutes. Some days her lips felt sore. Some days the notes still squeaked. Still, she colored in one square on her chart each time.

By winter, the squeaks were rare. By spring, she could play a whole song without stopping. Her band teacher, Mr. Okafor, asked her to play a short solo at the spring concert.

On the night of the concert, Amara's hands shook as she stood up. Then she remembered all the colored squares. She took a deep breath and played. The notes rang out clear and bright.

Afterward, a younger student came up to her. "I just started trumpet," he said. "I sound terrible." Amara smiled. "So did I," she said. "Want to see my chart?"$q$, 'draft')
