  ('b45f0f07-ebd6-52be-a6d0-ff53270830b6', null, (select id from public.skills where slug = 'read-g4-theme-summary'), null, 'hard',
   $q$How does the speaker change from the first stanza to the last stanza?$q$, $q$[{"text":"The speaker goes from loving kites to deciding never to fly one again.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The speaker goes from rushing and pulling hard to understanding patience.","is_correct":true},{"text":"The speaker goes from flying alone to flying kites with many friends.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The speaker goes from following Grandpa's advice to ignoring it.","is_correct":false,"misconception_token":"reverses-change"}]$q$::jsonb, $q$The speaker goes from rushing and pulling hard to understanding patience.$q$, $q$In stanza one the speaker yanks "hard and fast," and in the last stanza the speaker has learned to hold on "a little less." The speaker follows Grandpa's advice, so that choice has the change backward.$q$, 'draft', '60380577-c54a-532a-8e39-a499db1f8741')
